package io.github.leetcode.tree;

import io.github.leetcode.tree.TreeNodes.TreeNode;

import java.util.ArrayDeque;
import java.util.Queue;

public class EvenOddTree {

    public boolean isEvenOddTree(TreeNode root) {

        Queue<TreeNode> q = new ArrayDeque<>();
        q.add(root);
        int level = 0;

        while (q.size() > 0) {
            int size = q.size();
            int prev = 0;

            while (size-- > 0) {
                TreeNode temp = q.poll();
                int val = temp.val;

                if (level % 2 == 0) {

                    if (temp.val % 2 == 0) return false;
                    if (prev != 0 && prev >= val) return false;

                } else {

                    if (temp.val % 2 != 0) return false;
                    if (prev != 0 && prev <= val) return false;

                }

                if (temp.left != null) q.add(temp.left);
                if (temp.right != null) q.add(temp.right);
                prev = val;

            }

            level++;
        }

        return true;
    }

}

# Definition for a binary tree node.
# class TreeNode(object):
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution(object):
    def isEvenOddTree(self, root):
        """
        :type root: TreeNode
        :rtype: bool
        """
        if root is None:
            return True
        cur_level_cnt = 0
        cur_level = [root]
        while len(cur_level) > 0:
            next_level = []
            prev_num = None
            for cur_node in cur_level:
                if cur_level_cnt % 2 == 0:
                    if cur_node.val % 2 == 0:
                        return False
                    if prev_num is not None and cur_node.val <= prev_num:
                        return False
                    prev_num = cur_node.val
                else:
                    if cur_node.val % 2 != 0:
                        return False
                    if prev_num is not None and cur_node.val >= prev_num:
                        return False
                    prev_num = cur_node.val
                if cur_node.left is not None:
                    next_level.append(cur_node.left)
                if cur_node.right is not None:
                    next_level.append(cur_node.right)
            cur_level = next_level
            cur_level_cnt += 1
        return True
